    ev('2000-11-01', 'Business realignment and tracking stocks announced', 'WorldCom announced a realignment of its businesses and, subject to shareholder approval, two separately traded tracking stocks: WorldCom group and MCI group. The Committee\'s account places the largest accrual releases in the quarters around this announcement.', '10k-2000', 7, 'On November 1, 2000, we announced a realignment of our businesses with the', 'disclosure', '5'),
    ev('2001', '"Close the Gap"', 'Throughout much of 2001, Business Operations and Revenue Accounting tracked the gulf between projected and target revenue and found items to bridge it — a process presented to Ebbers and Sullivan as "Close the Gap".', B, 19, 'subtler but equally effective process was called “Close the Gap.”', 'mechanism', '14'),
    ev('2001-04', 'Q1 2001: line costs moved to capital accounts', 'With accruals exhausted, $544 million of operating line costs were capitalized as "prepaid capacity" and line costs were reduced by $771 million in total, taking the reported line-cost ratio to 42% instead of 50%.', B, 110, 'WorldCom capitalized $544 million of line costs in the first quarter and, with other adjustments, reduced line costs by a total of $771 million', 'mechanism', '105'),
