    ev('2001-10', 'Q3 2001: $743 million capitalized', 'A further $743 million of operating line costs was capitalized for the third quarter.', B, 115, 'WorldCom capitalized an additional $743 million of operating line costs for the third quarter', 'mechanism', '110'),
    ev('2002-01', 'Q4 2001: $941 million reduction', 'Fourth-quarter line costs were reduced by $941 million, $841 million of it capitalized; reported pre-tax income of $401 million replaced a $440 million loss.', B, 119, 'WorldCom reduced line costs by $941 million in the fourth quarter, capitalizing $841 million of that amount', 'mechanism', '114'),
