    ev('2002-05-29', 'Internal Audit finds the "prepaid capacity" entries', 'Cynthia Cooper\'s Internal Audit team, auditing capital expenditures, met with Sanjeev Sethi on May 29, 2002 about differences between capital-expenditure reports; the trail led to the prepaid-capacity entries.', B, 129, 'On May 29, 2002, Internal Audit met with Sethi to discuss differences between several types of internal capital expenditure reports', 'whistleblower', '124'),
    ev('2002-06-17', 'No support for the entries', 'On June 17, 2002, Cynthia Cooper and Glyn Smith of Internal Audit asked Betty Vinson about the prepaid-capacity entries; she said she had made an entry but did not know what it was for. Buford Yates sent them to David Myers, who said he had no support for the entries and would not create any.', B, 130, 'On June 17, 2002, Cooper and Smith went to Vinson from General Accounting to discuss the prepaid capacity entries', 'whistleblower', '125'),
