    ev('2002-07-08', 'House hearing: "Wrong Numbers"', 'Before the House Financial Services Committee, Ebbers and Sullivan invoked the Fifth Amendment; Jack Grubman, Bert Roberts, John Sidgmore and Andersen\'s Melvin Dick testified.', 'house-hearing-2002-07-08', 25, 'based on my fifth amendment constitutional rights', 'congress', '25'),
